+func (dr *dateTimeRange) ParseDates(dateTimeParser analysis.DateTimeParser) (start, end time.Time, err error) {
+	start = dr.Start
+	if dr.Start.IsZero() && dr.startString != nil {
+		s, _, parseError := dateTimeParser.ParseDateTime(*dr.startString)
